begin;

create table public."Dim_GrupoLabor" (
  "Id_Grupo_Labor" bigint generated by default as identity primary key,
  "DescripcionLabor" character varying not null,
  "TIPO_GRUPO" smallint not null
);

comment on table public."Dim_GrupoLabor" is
  'Catálogo maestro de grupos de labor para clasificar conceptos y movimientos de mano de obra.';
comment on column public."Dim_GrupoLabor"."TIPO_GRUPO" is
  'Clasificación del grupo de labor según el origen funcional del catálogo.';

alter table public."Dim_GrupoLabor" enable row level security;

revoke all on table public."Dim_GrupoLabor" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_GrupoLabor" to authenticated;

create policy dim_grupo_labor_select_admin
on public."Dim_GrupoLabor"
for select to authenticated
using ((select private.is_admin()));

create policy dim_grupo_labor_insert_admin
on public."Dim_GrupoLabor"
for insert to authenticated
with check ((select private.is_admin()));

create policy dim_grupo_labor_update_admin
on public."Dim_GrupoLabor"
for update to authenticated
using ((select private.is_admin()))
with check ((select private.is_admin()));

create policy dim_grupo_labor_delete_admin
on public."Dim_GrupoLabor"
for delete to authenticated
using ((select private.is_admin()));

insert into public."Dim_GrupoLabor" ("Id_Grupo_Labor", "DescripcionLabor", "TIPO_GRUPO") values
  (1, '001 - SANIDAD', 1),
  (2, '002 - RIEGO Y FERTIRRIEGO', 1),
  (3, '003 - LABORES CULTURALES', 1),
  (4, '004 - COSECHA', 1),
  (5, '005 - OPERADOR DE MAQUINARIA', 1),
  (6, '006 - JEFATURA CAMPO - OTROS', 1),
  (7, '007 - ADMINISTRATIVOS', 1),
  (9, '009 - OTRAS LABORES', 1),
  (10, '010 - MANTENIMIENTO DE MAQUINARIAS', 1),
  (11, '011 - DESCANSOS Y SUBSIDIOS', 1),
  (12, '012 - GUARDIANIA', 2);

select setval(
  pg_get_serial_sequence('public."Dim_GrupoLabor"', 'Id_Grupo_Labor'),
  (select max("Id_Grupo_Labor") from public."Dim_GrupoLabor"),
  true
);

do $$
declare
  v_sequence regclass := pg_get_serial_sequence('public."Dim_GrupoLabor"', 'Id_Grupo_Labor');
begin
  execute format('grant usage, select on sequence %s to authenticated', v_sequence);
end;
$$;

commit;
